"""Локализация: русский и английский. tr('ключ', n=3) подставляет значения в {n}."""
import json
from .paths import SETTINGS_FILE

LANG = "ru"

def set_lang(lang):
    global LANG
    LANG = lang if lang in ("ru", "en") else "ru"
    try:
        s = load_settings(); s["lang"] = LANG
        SETTINGS_FILE.write_text(json.dumps(s), encoding="utf-8")
    except OSError:
        pass

def load_settings():
    try:
        return json.loads(SETTINGS_FILE.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return {}

def init_lang():
    global LANG
    LANG = load_settings().get("lang", "ru")

